import{_ as e,o as a,c as i,an as l}from"./chunks/framework.DwXkzB5Y.js";const g=JSON.parse('{"title":"Parameters","description":"","frontmatter":{},"headers":[],"relativePath":"manual/parameters.md","filePath":"manual/parameters.md","lastUpdated":null}'),r={name:"manual/parameters.md"};function d(o,t,s,n,h,c){return a(),i("div",null,[...t[0]||(t[0]=[l(`<h1 id="Parameters" tabindex="-1">Parameters <a class="header-anchor" href="#Parameters" aria-label="Permalink to &quot;Parameters {#Parameters}&quot;">​</a></h1><p>The behavioural traits of an organism are held beside its heat-exchange traits in an <a href="/BiophysicalBehaviour.jl/previews/PR28/api#BiophysicalBehaviour.OrganismTraits"><code>OrganismTraits</code></a>. This page lists them. For the heat-exchange traits see <a href="https://biophysicalecology.github.io/HeatExchange.jl/dev/manual/parameters" target="_blank" rel="noreferrer">Parameters</a> in the documentation of HeatExchange.jl.</p><h2 id="The-structure" tabindex="-1">The structure <a class="header-anchor" href="#The-structure" aria-label="Permalink to &quot;The structure {#The-structure}&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Organism</span></span>
<span class="line"><span>├─ body                         a Body or CompositeBody (BiophysicalGeometry.jl)</span></span>
<span class="line"><span>└─ traits :: OrganismTraits</span></span>
<span class="line"><span>   ├─ thermal_strategy          Ectotherm(), Endotherm() or Heterotherm()</span></span>
<span class="line"><span>   ├─ heat_exchange             HeatExchangeTraits, or a NamedTuple of them by part</span></span>
<span class="line"><span>   ├─ behavior :: BehavioralTraits</span></span>
<span class="line"><span>   │  ├─ thermoregulation       EctothermBehavioralLimits or ThermoregulationLimits</span></span>
<span class="line"><span>   │  │  └─ control             RuleBasedSequentialControl or IPOPTControl</span></span>
<span class="line"><span>   │  └─ activity_period        Diurnal(), Nocturnal(), Crepuscular(), ...</span></span>
<span class="line"><span>   ├─ lung_part                 the name of the part that holds the lungs</span></span>
<span class="line"><span>   └─ couplings                 a HeatCoupling for each join of a CompositeBody</span></span></code></pre></div><table tabindex="0"><thead><tr><th style="text-align:left;">Accessor</th><th style="text-align:left;">Returns</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/BiophysicalBehaviour.jl/previews/PR28/api#BiophysicalBehaviour.thermal_strategy"><code>thermal_strategy</code></a></td><td style="text-align:left;">the thermal strategy</td></tr><tr><td style="text-align:left;"><a href="/BiophysicalBehaviour.jl/previews/PR28/api#BiophysicalBehaviour.heat_exchange"><code>heat_exchange</code></a></td><td style="text-align:left;">the heat-exchange traits</td></tr><tr><td style="text-align:left;"><a href="/BiophysicalBehaviour.jl/previews/PR28/api#BiophysicalBehaviour.behavior"><code>behavior</code></a></td><td style="text-align:left;">the <code>BehavioralTraits</code></td></tr><tr><td style="text-align:left;"><a href="/BiophysicalBehaviour.jl/previews/PR28/api#BiophysicalBehaviour.thermoregulation"><code>thermoregulation</code></a></td><td style="text-align:left;">the limits struct</td></tr><tr><td style="text-align:left;"><a href="/BiophysicalBehaviour.jl/previews/PR28/api#BiophysicalBehaviour.control_strategy"><code>control_strategy</code></a></td><td style="text-align:left;">the controller</td></tr><tr><td style="text-align:left;"><a href="/BiophysicalBehaviour.jl/previews/PR28/api#BiophysicalBehaviour.activity_period"><code>activity_period</code></a></td><td style="text-align:left;">the activity period</td></tr><tr><td style="text-align:left;"><a href="/BiophysicalBehaviour.jl/previews/PR28/api#BiophysicalBehaviour.lung_part"><code>lung_part</code></a>, <a href="/BiophysicalBehaviour.jl/previews/PR28/api#BiophysicalBehaviour.couplings"><code>couplings</code></a></td><td style="text-align:left;">the lung part and the couplings</td></tr><tr><td style="text-align:left;"><a href="/BiophysicalBehaviour.jl/previews/PR28/api#BiophysicalBehaviour.physiology"><code>physiology</code></a></td><td style="text-align:left;">the heat-exchange traits by part, with the lung part marked</td></tr></tbody></table><p>Each takes an <code>Organism</code> or an <code>OrganismTraits</code>.</p><h2 id="A-range-of-a-parameter" tabindex="-1">A range of a parameter <a class="header-anchor" href="#A-range-of-a-parameter" aria-label="Permalink to &quot;A range of a parameter {#A-range-of-a-parameter}&quot;">​</a></h2><p>A <a href="/BiophysicalBehaviour.jl/previews/PR28/api#BiophysicalBehaviour.SteppedParameter"><code>SteppedParameter</code></a> is a parameter that the organism can change:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>current</code></td><td style="text-align:left;">the present value</td></tr><tr><td style="text-align:left;"><code>reference</code></td><td style="text-align:left;">the resting value. Defaults to <code>current</code></td></tr><tr><td style="text-align:left;"><code>max</code></td><td style="text-align:left;">the limit</td></tr><tr><td style="text-align:left;"><code>step</code></td><td style="text-align:left;">the increment of one action of the rule-based controller</td></tr></tbody></table><h2 id="Ectotherms" tabindex="-1">Ectotherms <a class="header-anchor" href="#Ectotherms" aria-label="Permalink to &quot;Ectotherms {#Ectotherms}&quot;">​</a></h2><p><a href="/BiophysicalBehaviour.jl/previews/PR28/api#BiophysicalBehaviour.EctothermBehavioralLimits"><code>EctothermBehavioralLimits</code></a>, with the defaults of <code>example_ectotherm_behavioral_limits</code>, which are those of the NicheMapR ectotherm model:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">limits </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> example_ectotherm_behavioral_limits</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span></code></pre></div><div class="vp-raw-html"><div class="markdown"><table><tr><th align="left">Field</th><th align="left">Default</th><th align="left">Meaning</th></tr><tr><td align="left"><code>shade</code></td><td align="left">0.0 to 0.9, step 0.03</td><td align="left">shade fraction</td></tr><tr><td align="left"><code>depth</code></td><td align="left">node 1 to the deepest, step 1</td><td align="left">soil node. 1 is the surface</td></tr><tr><td align="left"><code>depth_min_underground</code></td><td align="left">2.0</td><td align="left">shallowest node of a retreat</td></tr><tr><td align="left"><code>height</code></td><td align="left">node 1 to the highest, step 1</td><td align="left">height node</td></tr><tr><td align="left"><code>absorptivity</code></td><td align="left">0.9 to 0.9, step 0.0</td><td align="left">solar absorptivity</td></tr><tr><td align="left"><code>pant_rate</code></td><td align="left">1.0 to 1.0, step 0.1</td><td align="left">multiplier on ventilation</td></tr><tr><td align="left"><code>target_temperature</code></td><td align="left">30.0 °C to 34.0 °C, step 0.5 K</td><td align="left">preferred body temperature, raised towards the maximum for activity</td></tr><tr><td align="left"><code>active_temperature_min</code></td><td align="left">24.0 °C</td><td align="left">lower limit for activity</td></tr><tr><td align="left"><code>active_temperature_max</code></td><td align="left">34.0 °C</td><td align="left">upper limit for activity</td></tr><tr><td align="left"><code>basking_temperature_min</code></td><td align="left">17.5 °C</td><td align="left">lower limit for basking</td></tr><tr><td align="left"><code>emerge_temperature_min</code></td><td align="left">15.0 °C</td><td align="left">soil temperature at which the animal can leave its retreat</td></tr><tr><td align="left"><code>critical_temperature_min</code></td><td align="left">6.0 °C</td><td align="left">critical thermal minimum</td></tr><tr><td align="left"><code>critical_temperature_max</code></td><td align="left">40.0 °C</td><td align="left">critical thermal maximum</td></tr><tr><td align="left"><code>can_retreat_underground</code></td><td align="left">true</td><td align="left"></td></tr><tr><td align="left"><code>can_seek_shade</code></td><td align="left">true</td><td align="left"></td></tr><tr><td align="left"><code>can_climb</code></td><td align="left">false</td><td align="left"></td></tr><tr><td align="left"><code>can_solar_orient</code></td><td align="left">true</td><td align="left">turn broadside to the sun to bask</td></tr><tr><td align="left"><code>can_press_to_ground</code></td><td align="left">true</td><td align="left"></td></tr><tr><td align="left"><code>can_change_absorptivity</code></td><td align="left">false</td><td align="left"></td></tr><tr><td align="left"><code>can_pant</code></td><td align="left">false</td><td align="left"></td></tr><tr><td align="left"><code>solve_underground</code></td><td align="left">false</td><td align="left">solve the heat budget in the retreat, or take soil temperature</td></tr><tr><td align="left"><code>burrow_shade_mode</code></td><td align="left">MaxShadeOnly</td><td align="left">which microclimate the retreat is in</td></tr><tr><td align="left"><code>emerge_signal</code></td><td align="left">0.0 K hr^-1</td><td align="left">rate of change of soil temperature needed to emerge. Zero for none</td></tr></table>
</div></div><p>Two more fields, <code>sun_orientation</code> and <code>pressed_to_ground</code>, record the posture chosen in the current hour.</p><h2 id="Endotherms" tabindex="-1">Endotherms <a class="header-anchor" href="#Endotherms" aria-label="Permalink to &quot;Endotherms {#Endotherms}&quot;">​</a></h2><p><a href="/BiophysicalBehaviour.jl/previews/PR28/api#BiophysicalBehaviour.ThermoregulationLimits"><code>ThermoregulationLimits</code></a>, with the defaults of <code>example_thermoregulation_limits</code>:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">limits </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> example_thermoregulation_limits</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span></code></pre></div><div class="vp-raw-html"><div class="markdown"><table><tr><th align="left">Field</th><th align="left">Default</th><th align="left">Meaning</th></tr><tr><td align="left"><code>control</code></td><td align="left">RuleBasedSequentialControl</td><td align="left">the controller</td></tr><tr><td align="left"><code>minimum_heat_flow</code></td><td align="left">77.62 W</td><td align="left">least metabolic heat production</td></tr><tr><td align="left"><code>insulation.dorsal</code>, <code>.ventral</code></td><td align="left">0.002 m to 0.002 m</td><td align="left">depth of the coat. The step is a fraction of fibre length</td></tr><tr><td align="left"><code>axis_ratio_factor</code></td><td align="left">1.1 to 5.0, step 0.1</td><td align="left">ratio of the long axis of the body to the short</td></tr><tr><td align="left"><code>flesh_conductivity</code></td><td align="left">0.9 W K^-1 m^-1 to 2.8 W K^-1 m^-1, step 0.1 W K^-1 m^-1</td><td align="left">thermal conductivity of flesh</td></tr><tr><td align="left"><code>core_temperature</code></td><td align="left">37.0 °C to 39.0 °C, step 0.1 K</td><td align="left">core temperature</td></tr><tr><td align="left"><code>panting.pant</code></td><td align="left">1.0 to 10.0, step 0.1</td><td align="left">multiplier on ventilation</td></tr><tr><td align="left"><code>panting.multiplier</code></td><td align="left">1.05</td><td align="left">metabolic rate at full panting, as a multiple of the minimum</td></tr><tr><td align="left"><code>skin_wetness</code></td><td align="left">0.005 to 1.0, step 0.001</td><td align="left">fraction of the skin that is wet</td></tr></table>
</div></div><p>The remaining fields are used only by <a href="/BiophysicalBehaviour.jl/previews/PR28/api#BiophysicalBehaviour.IPOPTControl"><code>IPOPTControl</code></a>, see <a href="./optimisation">Thermoregulation by optimisation</a>:</p><div class="vp-raw-html"><div class="markdown"><table><tr><th align="left">Field</th><th align="left">Default</th><th align="left">Meaning</th></tr><tr><td align="left"><code>core_temperature_weight</code></td><td align="left">1.0</td><td align="left">weight on core temperature away from the setpoint</td></tr><tr><td align="left"><code>metabolic_heat_weight</code></td><td align="left">0.1</td><td align="left">weight on heat production above the minimum</td></tr><tr><td align="left"><code>panting_weight</code></td><td align="left">1.0</td><td align="left">weight on panting</td></tr><tr><td align="left"><code>skin_wetness_weight</code></td><td align="left">1.0</td><td align="left">weight on skin wetness</td></tr><tr><td align="left"><code>flesh_conductivity_weight</code></td><td align="left">0.0</td><td align="left">weight on flesh conductivity</td></tr><tr><td align="left"><code>gradient_weight</code></td><td align="left">0.0</td><td align="left">weight on the core-to-skin temperature difference</td></tr><tr><td align="left"><code>target_core_skin_gradient</code></td><td align="left">2.0 K</td><td align="left">the difference that <code>gradient_weight</code> holds to</td></tr><tr><td align="left"><code>skin_temperature_undershoot</code></td><td align="left">5.0 K</td><td align="left">lower bound of skin and surface temperature, below air temperature</td></tr><tr><td align="left"><code>skin_temperature_core_overshoot</code></td><td align="left">5.0 K</td><td align="left">upper bound of skin and surface temperature, above the maximum core temperature</td></tr><tr><td align="left"><code>metabolic_heat_flow_max_multiplier</code></td><td align="left">20.0</td><td align="left">upper bound of heat production, as a multiple of the minimum</td></tr><tr><td align="left"><code>minimum_normalisation_range</code></td><td align="left">1.0e-6</td><td align="left">floor on the ranges that normalise the objective</td></tr></table>
</div></div><h2 id="Controllers" tabindex="-1">Controllers <a class="header-anchor" href="#Controllers" aria-label="Permalink to &quot;Controllers {#Controllers}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Controller</th><th style="text-align:left;">Fields</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/BiophysicalBehaviour.jl/previews/PR28/api#BiophysicalBehaviour.RuleBasedSequentialControl"><code>RuleBasedSequentialControl</code></a></td><td style="text-align:left;"><code>mode</code>, an <a href="/BiophysicalBehaviour.jl/previews/PR28/api#BiophysicalBehaviour.AbstractThermoregulationMode"><code>AbstractThermoregulationMode</code></a>, default <code>CoreFirst()</code>; <code>tolerance</code>, the fraction below the minimum metabolic rate that is accepted, default 0.005; <code>max_iterations</code>, default 1000</td></tr><tr><td style="text-align:left;"><a href="/BiophysicalBehaviour.jl/previews/PR28/api#BiophysicalBehaviour.IPOPTControl"><code>IPOPTControl</code></a></td><td style="text-align:left;"><code>nlp_strategy</code>, default <code>MultipartNLP()</code>; <code>smoothing</code>, default <code>SmoothBound(1e-5)</code></td></tr></tbody></table><h2 id="Example-constructors" tabindex="-1">Example constructors <a class="header-anchor" href="#Example-constructors" aria-label="Permalink to &quot;Example constructors {#Example-constructors}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Function</th><th style="text-align:left;">Builds</th></tr></thead><tbody><tr><td style="text-align:left;"><code>example_ectotherm_behavioral_limits</code></td><td style="text-align:left;"><a href="/BiophysicalBehaviour.jl/previews/PR28/api#BiophysicalBehaviour.EctothermBehavioralLimits"><code>EctothermBehavioralLimits</code></a></td></tr><tr><td style="text-align:left;"><code>example_ectotherm_behavioral_traits</code></td><td style="text-align:left;"><a href="/BiophysicalBehaviour.jl/previews/PR28/api#BiophysicalBehaviour.BehavioralTraits"><code>BehavioralTraits</code></a> of an ectotherm, with an <code>activity_period</code></td></tr><tr><td style="text-align:left;"><code>example_ectotherm_organism_traits</code></td><td style="text-align:left;"><a href="/BiophysicalBehaviour.jl/previews/PR28/api#BiophysicalBehaviour.OrganismTraits"><code>OrganismTraits</code></a> of an ectotherm. Keywords go to the limits</td></tr><tr><td style="text-align:left;"><code>example_thermoregulation_limits</code></td><td style="text-align:left;"><a href="/BiophysicalBehaviour.jl/previews/PR28/api#BiophysicalBehaviour.ThermoregulationLimits"><code>ThermoregulationLimits</code></a></td></tr><tr><td style="text-align:left;"><code>example_behavioral_traits</code></td><td style="text-align:left;"><a href="/BiophysicalBehaviour.jl/previews/PR28/api#BiophysicalBehaviour.BehavioralTraits"><code>BehavioralTraits</code></a> of an endotherm</td></tr><tr><td style="text-align:left;"><code>example_organism_traits</code></td><td style="text-align:left;"><a href="/BiophysicalBehaviour.jl/previews/PR28/api#BiophysicalBehaviour.OrganismTraits"><code>OrganismTraits</code></a> of an endotherm. Keywords go to <code>example_heat_exchange_traits</code></td></tr></tbody></table><p>A limits struct is immutable. To change one field of an existing one, use <code>@set</code> of <a href="https://github.com/jw3126/Setfield.jl" target="_blank" rel="noreferrer">Setfield.jl</a>, as the package itself does:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Setfield</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> @set</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">limits </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> @set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> limits</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flesh_conductivity</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">max </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;W/m/K&quot;</span></span></code></pre></div>`,26)])])}const f=e(r,[["render",d]]);export{g as __pageData,f as default};
